export const languages={java:{name:'Java 17',file:'Solution.java'},python:{name:'Python 3.11',file:'solution.py'},c:{name:'C',file:'solution.c'},cpp:{name:'C++',file:'solution.cpp'}};
const ct=t=>({int:'int',boolean:'bool',String:'const char*','int[]':'IntArray'}[t]),cppType=t=>({int:'int',boolean:'bool',String:'string','int[]':'vector<int>'}[t]);
export function starterFor(p,l){if(l==='java')return p.starter;if(l==='python')return 'def '+p.method+'('+p.params.map(x=>x.name).join(', ')+'):\n    # Return the result; do not read stdin.\n    raise NotImplementedError("Your turn")\n';if(l==='cpp')return '#include <vector>\n#include <string>\n#include <unordered_map>\n#include <algorithm>\n#include <stdexcept>\nusing namespace std;\n\n'+cppType(p.returns)+' '+p.method+'('+p.params.map(x=>(x.type==='int[]'?'const vector<int>&':x.type==='String'?'const string&':cppType(x.type))+' '+x.name).join(', ')+') {\n    // Implement your solution.\n    return {};\n}\n';return '#include <stdbool.h>\n#include <stdlib.h>\n// Return arrays using {data, length}; use malloc or static storage.\ntypedef struct { int *data; int length; } IntArray;\n\n'+ct(p.returns)+' '+p.method+'('+p.params.flatMap(x=>x.type==='int[]'?['const int *'+x.name,'int '+x.name+'_len']:[ct(x.type)+' '+x.name]).join(', ')+') {\n    '+(p.returns==='int[]'?'return (IntArray){NULL, 0};':p.returns==='String'?'return "";':p.returns==='boolean'?'return false;':'return 0;')+'\n}\n';}
export function cString(v){return '"'+[...v].map(c=>c==='"'?'\\"':c==='\\'?'\\\\':c.charCodeAt(0)<32||c.charCodeAt(0)===127?'\\'+c.charCodeAt(0).toString(8).padStart(3,'0'):c).join('')+'"';}
export function buildNativeProgram(source,p,cases,l){if(l==='python')return source+'\nimport json as _bqjson\n_bqcases=_bqjson.loads('+cString(JSON.stringify(cases))+')\nfor _i,_case in enumerate(_bqcases):\n    try:\n        _v='+p.method+'(*_case["args"])\n        print("\\n__BYTEQUEST_CASE_"+str(_i)+"__"+_bqjson.dumps({"ok":True,"actual":_v},separators=(",",":")))\n    except Exception as _e:\n        print("\\n__BYTEQUEST_CASE_"+str(_i)+"__"+_bqjson.dumps({"ok":False,"error":str(_e)[:200]}))\n';if(!['c','cpp'].includes(l))throw new Error('Choose C, C++ or Python.');const cpp=l==='cpp',literal=(v,t)=>t==='int[]'?(cpp?'vector<int>{'+v.join(',')+'}':'(int[]){'+(v.length?v.join(','):'0')+'}'):t==='String'?cString(v):String(v);const body=cases.map((c,i)=>{const args=c.args.flatMap((v,j)=>!cpp&&p.params[j].type==='int[]'?[literal(v,'int[]'),String(v.length)]:[literal(v,p.params[j].type)]).join(','),call=p.method+'('+args+')';if(cpp)return '{auto a='+call+';cout<<"\\n__BYTEQUEST_CASE_'+i+'__{\\\"ok\\\":true,\\\"actual\\\":"<<bqrepr(a)<<"}\\n";}';const repr=p.returns==='int[]'?'bqarray(a)':p.returns==='String'?'bqstr(a)':p.returns==='boolean'?'printf("%s",a?"true":"false")':'printf("%d",a)';return '{'+ct(p.returns)+' a='+call+';printf("\\n__BYTEQUEST_CASE_'+i+'__{\\\"ok\\\":true,\\\"actual\\\":");'+repr+';printf("}\\n");}';}).join('\n');if(cpp)return '#include <iostream>\n#include <sstream>\n#include <iomanip>\n#include <vector>\n#include <string>\n#include <algorithm>\n#include <stdexcept>\nusing namespace std;\n'+source+`\nstring bqrepr(int x){return to_string(x);}string bqrepr(bool x){return x?"true":"false";}string bqrepr(const string& x){ostringstream b;b<<'"';for(unsigned char c:x){if(c=='"'||c=='\\\\')b<<'\\\\'<<c;else if(c<32)b<<"\\\\u"<<hex<<setw(4)<<setfill('0')<<(int)c;else b<<c;}b<<'"';return b.str();}string bqrepr(const vector<int>&a){string s="[";for(size_t i=0;i<a.size();i++){if(i)s+=",";s+=to_string(a[i]);}return s+"]";}\nint main(){`+body+'return 0;}';return '#include <stdio.h>\n#include <stdbool.h>\n#include <stdlib.h>\n'+source+`\nvoid bqstr(const char*s){putchar('"');if(s)for(;*s;s++){unsigned char c=*s;if(c=='"'||c=='\\\\'){putchar('\\\\');putchar(c);}else if(c<32)printf("\\\\u%04x",c);else putchar(c);}putchar('"');}\n`+(p.returns==='int[]'?`void bqarray(IntArray a){putchar('[');for(int i=0;i<a.length&&i<10000;i++){if(i)putchar(',');printf("%d",a.data[i]);}putchar(']');}`:'')+'\nint main(void){'+body+'return 0;}';}
export function nativeResults(output,p,cases){const found=new Map();for(const line of output.split(/\r?\n/)){const m=line.match(/^__BYTEQUEST_CASE_(\d+)__(.*)$/);if(m)try{found.set(Number(m[1]),JSON.parse(m[2]));}catch{}}const norm=x=>p.normalize==='sort-int'&&Array.isArray(x)?[...x].sort((a,b)=>a-b):x;return cases.map((c,i)=>{const r=found.get(i);return{name:'Case '+(i+1)+': '+(c.label||'Practice'),passed:r?.ok===true&&JSON.stringify(norm(r.actual))===JSON.stringify(norm(c.expected)),actual:r?.ok?JSON.stringify(r.actual):r?.error||'No result (check return type or runtime error)',expected:JSON.stringify(c.expected)};});}
export class NativeJudge{
 constructor(onStatus=()=>{}){this.onStatus=onStatus;this.ready='serviceWorker' in navigator?navigator.serviceWorker.register(new URL('runtime-sw.js',import.meta.url),{scope:new URL('.',import.meta.url).pathname}).then(()=>navigator.serviceWorker.ready):Promise.reject(new Error('This browser cannot start the isolated compiler.'));this.ready.catch(()=>{});}
 async run(source,p,cases,l){const popup=window.open('about:blank','_blank','width=760,height=560');if(!popup)throw new Error('Allow ByteQuest’s compiler window, then try Run again.');this.popup=popup;try{await this.ready;}catch(e){popup.close();throw e;}const id=crypto.randomUUID();this.channel=new BroadcastChannel('bytequest-native-'+id);this.onStatus('Loading '+languages[l].name+' toolchain. Keep the compiler tab open.');const program=buildNativeProgram(source,p,cases,l),start=performance.now();return new Promise((resolve,reject)=>{this.reject=reject;this.timer=setTimeout(()=>this.stop(),120000);this.channel.onmessage=e=>{if(e.data?.type==='ready')this.channel.postMessage({type:'run',program,runtime:{python:'python',c:'clang',cpp:'clangpp'}[l]});if(e.data?.type==='result'){const r=e.data.result;this.finish();resolve(r.resultType!=='complete'||r.exitCode!==0?{status:'compile_error',message:((r.stderr||r.error?.message||'Compilation or execution failed.')+' Check syntax and the function signature. This C++ toolchain does not support exceptions.').slice(0,12000)}:{status:'ok',cases:nativeResults(r.stdout,p,cases),stdout:r.stdout.replace(/^__BYTEQUEST_CASE_.*$/gm,'').trim().slice(0,12000),elapsedMs:Math.round(performance.now()-start)});}if(e.data?.type==='error'){this.finish();reject(new Error(e.data.message));}};popup.location.href=new URL('native-runner.html#'+id,import.meta.url).href;});}
 finish(){clearTimeout(this.timer);this.channel?.postMessage({type:'close'});this.channel?.close();this.channel=null;this.popup=null;this.reject=null;}
 stop(){const reject=this.reject;this.channel?.postMessage({type:'close'});try{this.popup?.close();}catch{}this.finish();reject?.(new Error('Language run stopped or timed out. Your code is saved.'));}
}
